import copy, re, itertools

def find_brackets(text):
    bracket = {}
    for m in re.finditer('\[.*?\]', text):
        secret = 'N' + str(m.end())
        text = text.replace(m.group(), secret)

        p = m.start()+m.group().index('[') + 1
        e = m.end()

        for i in range(p, e):

            if text[i] == '[':
                bracket[text[i]] = i

    return secret, text

